 const schema=JSON.stringify([{'@context':'https://schema.org','@type':'SoftwareApplication',name,description,url,applicationCategory:'BusinessApplication',operatingSystem:'Any',isAccessibleForFree:true,offers:{'@type':'Offer',price:'0',priceCurrency:'USD'},publisher:{'@type':'Organization',name:'Pratix.io',url:'https://www.pratix.io/'}},{'@context':'https://schema.org','@type':'FAQPage',mainEntity:localizedFaq.map(f=>({'@type':'Question',name:f.q,acceptedAnswer:{'@type':'Answer',text:f.a}}))}]);
